CREATE TABLE IF NOT EXISTS economic_onboarding_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL, display_name text NOT NULL, business_type text NOT NULL, sector text NOT NULL, location text, description text, data_environment text NOT NULL DEFAULT 'production', onboarding_status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_economic_profiles_owner ON economic_onboarding_profiles(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS economic_evidence_vault (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, title text NOT NULL, category text NOT NULL, description text NOT NULL, source_type text NOT NULL, source_reference text, verification_status text NOT NULL DEFAULT 'submitted', trust_score numeric(5,2), verified_by text, verified_at timestamptz, review_notes text, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_economic_evidence_profile ON economic_evidence_vault(profile_id,created_at DESC);
CREATE TABLE IF NOT EXISTS economic_trusted_evidence_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_id uuid NOT NULL, profile_id uuid NOT NULL, signal_type text NOT NULL, signal_score numeric(5,2) NOT NULL, signal_summary text NOT NULL, source_verification_score numeric(5,2) NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_trusted_signal_aggregates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, signal_count integer NOT NULL DEFAULT 0, average_signal_score numeric(5,2) NOT NULL DEFAULT 0, weighted_score numeric(5,2) NOT NULL DEFAULT 0, confidence text NOT NULL DEFAULT 'low', signal_types jsonb NOT NULL DEFAULT '[]'::jsonb, source_ids jsonb NOT NULL DEFAULT '[]'::jsonb, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_intelligence_provenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, aggregate_id uuid NOT NULL, explanation text NOT NULL, contribution_breakdown jsonb NOT NULL DEFAULT '[]'::jsonb, source_signal_ids jsonb NOT NULL DEFAULT '[]'::jsonb, confidence text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_explainable_network_intelligence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, aggregate_id uuid NOT NULL, provenance_id uuid, network_score numeric(5,2) NOT NULL, confidence text NOT NULL, drivers jsonb NOT NULL DEFAULT '[]'::jsonb, source_signal_ids jsonb NOT NULL DEFAULT '[]'::jsonb, explanation text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_explainable_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, network_intelligence_id uuid NOT NULL, assessment_score numeric(5,2) NOT NULL, confidence text NOT NULL, drivers jsonb NOT NULL DEFAULT '[]'::jsonb, source_signal_ids jsonb NOT NULL DEFAULT '[]'::jsonb, explanation text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_explainable_consensus (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, network_intelligence_id uuid NOT NULL, assessment_id uuid NOT NULL, consensus_score numeric(5,2) NOT NULL, confidence text NOT NULL, decision_state text NOT NULL, drivers jsonb NOT NULL DEFAULT '[]'::jsonb, source_signal_ids jsonb NOT NULL DEFAULT '[]'::jsonb, explanation text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_explainable_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, consensus_id uuid NOT NULL, decision_state text NOT NULL, decision_score numeric(5,2) NOT NULL, confidence text NOT NULL, rationale text NOT NULL, risk_factors jsonb NOT NULL DEFAULT '[]'::jsonb, recommended_actions jsonb NOT NULL DEFAULT '[]'::jsonb, governance_requirements jsonb NOT NULL DEFAULT '[]'::jsonb, source_signal_ids jsonb NOT NULL DEFAULT '[]'::jsonb, auto_execution_allowed boolean NOT NULL DEFAULT false, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());